import SwiftUI

public enum TUIBulletType: String, CaseIterable, Sendable {
    case primary = "Bullet - Primary"
    case accent = "Bullet - Accent"
    case opposite = "Bullet - Opposite"

    public var figmaNodeID: String {
        switch self {
        case .primary: "53309:296334"
        case .accent: "53309:296336"
        case .opposite: "53480:295831"
        }
    }

    var color: Color {
        switch self {
        case .primary: TUIColor.accent
        case .accent: TUIColor.named("Status/Info", fallback: 0x428BF9)
        case .opposite: TUIColor.named("Background/Accent Opposite", fallback: 0x000000)
        }
    }
}

/// The 6 pt marker from the `.bullet` Figma component set.
public struct TUIBullet: View {
    public let type: TUIBulletType

    public init(type: TUIBulletType = .primary) {
        self.type = type
    }

    public var body: some View {
        Circle()
            .fill(type.color)
            .frame(width: 6, height: 6)
            .accessibilityIdentifier(type.figmaNodeID)
            .accessibilityLabel(type.rawValue)
    }
}

import SwiftUI

/// TUI's custom search input, styled to match the iOS design without replacing the system search API.
public struct TUISearchInput: View {
    public enum State: String, CaseIterable, Sendable {
        case normal
        case focus
        case disabled
        case pressed
    }

    @Binding private var text: String
    public let state: State
    public let placeholder: String
    @FocusState private var isFocused: Bool

    public init(
        text: Binding<String>,
        state: State = .normal,
        placeholder: String = "Поиск"
    ) {
        _text = text
        self.state = state
        self.placeholder = placeholder
    }

    private var isDisabled: Bool { state == .disabled }
    private var isFilled: Bool { !text.isEmpty }

    public var body: some View {
        HStack(spacing: state == .focus ? 3 : 0) {
            Image("tui-search-input-search", bundle: .module)
                .renderingMode(.template)
                .resizable()
                .frame(width: 24, height: 24)
                .foregroundStyle(TUIColor.named("Text/Secondary"))

            ZStack(alignment: .leading) {
                if text.isEmpty {
                    Text(placeholder)
                        .tuiTypography(.bodyLarge)
                        .foregroundStyle(TUIColor.named("Text/Secondary"))
                        .accessibilityHidden(true)
                }
                TextField("", text: $text)
                    .tuiTypography(.bodyLarge)
                    .foregroundStyle(text.isEmpty ? Color.clear : TUIColor.named("Text/Primary"))
                    .tint(TUIColor.named("Background/Accent 2"))
                    .focused($isFocused)
                    .disabled(isDisabled || state == .pressed)
                    .accessibilityLabel(placeholder)
            }
            .padding(.leading, 3)

            if isFilled && !isDisabled {
                Button {
                    text = ""
                } label: {
                    Image("tui-search-input-clear", bundle: .module)
                        .renderingMode(.template)
                        .resizable()
                        .frame(width: 16, height: 16)
                        .foregroundStyle(TUIColor.named("Text/Secondary"))
                        .frame(width: 32, height: 36)
                        .contentShape(Rectangle())
                }
                .buttonStyle(.plain)
                .accessibilityLabel("Очистить поиск")
            } else if state == .normal || state == .pressed || isDisabled {
                Color.clear.frame(width: 8)
            }
        }
        .padding(.leading, 4)
        .padding(.trailing, isFilled && !isDisabled ? 0 : 8)
        .frame(height: 36)
        .background(
            TUIColor.named(state == .pressed ? "State/Background/Neutral 2 Pressed" : "Background/Neutral 2"),
            in: RoundedRectangle(cornerRadius: 10)
        )
        .clipShape(RoundedRectangle(cornerRadius: 10))
        .opacity(isDisabled ? 0.5 : 1)
        .onAppear { isFocused = state == .focus }
        .onChange(of: state) { _, newState in isFocused = newState == .focus }
    }
}

import SwiftUI

/// A payment-network mark exported from the corresponding TUI Mobile Figma component.
public struct TUIPaymentLogo: View {
    public enum Network: String, CaseIterable, Identifiable, Sendable {
        case maestro
        case mastercard
        case mastercardGold = "mastercard-gold"
        case mastercardMetal = "mastercard-metal"
        case mastercardMetalInverse = "mastercard-metal-inverse"
        case mir
        case mirMonochrome = "mir-monochrome"
        case mirSupreme = "mir-supreme"
        case mirSupremeMetall = "mir-supreme-metall"
        case unionpay
        case unionpayMonochrome = "unionpay-monochrome"
        case visa
        case visaMonochrome = "visa-monochrome"

        public var id: String { rawValue }

        public var figmaNodeID: String {
            switch self {
            case .mastercardMetal: "45931:47329"
            case .maestro: "45931:47327"
            case .mastercard: "45931:47325"
            case .mastercardGold: "45931:47331"
            case .mastercardMetalInverse: "45931:47333"
            case .mir: "45931:47335"
            case .mirMonochrome: "45931:47337"
            case .unionpay: "45931:47339"
            case .unionpayMonochrome: "45931:47341"
            case .visa: "45931:47343"
            case .visaMonochrome: "45931:47345"
            case .mirSupreme: "98597:29047"
            case .mirSupremeMetall: "98597:29055"
            }
        }

        fileprivate var artworkWidth: CGFloat {
            switch self {
            case .mir, .mirMonochrome, .visa, .visaMonochrome: 40
            case .mirSupreme, .mirSupremeMetall: 35
            default: 32
            }
        }

        fileprivate var leadingInset: CGFloat {
            switch self {
            case .mir, .mirMonochrome, .visa, .visaMonochrome: 3
            case .mirSupreme, .mirSupremeMetall: 8
            default: 11
            }
        }
    }

    public let network: Network

    public init(_ network: Network = .mastercardMetal) {
        self.network = network
    }

    public var body: some View {
        HStack(spacing: 0) {
            Color.clear.frame(width: network.leadingInset)
            Image("tui-payment-logo-\(network.rawValue)", bundle: .module)
                .resizable()
                .interpolation(.high)
                .frame(width: network.artworkWidth, height: 24)
        }
        .frame(width: 43, height: 24, alignment: .leading)
        .clipped()
        .accessibilityHidden(true)
    }
}

