import SwiftUI
import UIKit

public enum TUINotificationBadgeSize: String, CaseIterable, Sendable {
    case small
    case medium
    case large

    public var figmaNodeID: String {
        switch self {
        case .small: "25738:689221"
        case .medium: "25738:689224"
        case .large: "25738:689222"
        }
    }
}

/// Notification badge from TUI Mobile; `small` is the textless 6-point dot.
/// The parent owns accessibility: announce the actual count on its label/value,
/// including when the visible badge reads "99+". The badge is not a focus stop.
public struct TUINotificationBadge: View {
    public static let figmaComponentSetID = "25738:689227"
    public let text: String
    public let size: TUINotificationBadgeSize
    @Environment(\.dynamicTypeSize) private var typeSize

    public init(_ text: String = "1", size: TUINotificationBadgeSize = .medium) {
        self.text = text
        self.size = size
    }

    public var body: some View {
        Group {
            if size == .small {
                Circle()
                    .fill(TUIColor.named("Component/Badge Notification"))
                    .frame(width: 6, height: 6)
                    .accessibilityHidden(true)
            } else {
                let role: TUITypographyRole = size == .large ? .bodyMedium : .uiSmall
                TUINotificationBadgeLayout(size: size) {
                    Text(text)
                        .font(Font(scaledFont(role: role)))
                        .foregroundStyle(TUIColor.named("Text/Primary On Dark"))
                        .lineLimit(1)
                        .fixedSize()
                        .accessibilityHidden(true)
                }
                .background(TUIColor.named("Component/Badge Notification"), in: Capsule())
            }
        }
        .accessibilityHidden(true)
    }

    private func scaledFont(role: TUITypographyRole) -> UIFont {
        let category: UIContentSizeCategory
        switch min(typeSize, .accessibility1) {
        case .xSmall: category = .extraSmall
        case .small: category = .small
        case .medium: category = .medium
        case .large: category = .large
        case .xLarge: category = .extraLarge
        case .xxLarge: category = .extraExtraLarge
        case .xxxLarge: category = .extraExtraExtraLarge
        default: category = .accessibilityMedium
        }
        return UIFontMetrics(forTextStyle: role.textStyle.uiKitTextStyle)
            .scaledFont(for: role.metrics.nativeFont(at: role.metrics.size),
                        compatibleWith: UITraitCollection(preferredContentSizeCategory: category))
    }
}

private struct TUINotificationBadgeLayout: Layout {
    let size: TUINotificationBadgeSize

    private func geometry(_ subview: LayoutSubview) -> CGSize {
        let label = subview.sizeThatFits(.unspecified)
        let minimum: CGFloat = size == .large ? TUISpacing.x6 : 18
        let height = max(minimum, ceil(label.height) + 2)
        // The current structure table specifies 23% / 22%. Preserve the source
        // variants' exact base insets; enlarged insets round to a whole point.
        let inset: CGFloat = height == minimum ? (size == .large ? 5.5 : TUISpacing.x1)
            : (height * (size == .large ? 0.23 : 0.22)).rounded()
        return CGSize(width: max(height, label.width + 2 * inset), height: height)
    }

    func sizeThatFits(proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) -> CGSize {
        geometry(subviews[0])
    }

    func placeSubviews(in bounds: CGRect, proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) {
        // Medium's source has top 0.5 / bottom 1.5 at its minimum height.
        let offset: CGFloat = size == .medium && bounds.height == 18 ? -0.5 : 0
        subviews[0].place(at: CGPoint(x: bounds.midX, y: bounds.midY + offset), anchor: .center,
                          proposal: .unspecified)
    }
}

import SwiftUI

public enum TUIBadgedContentBadge: String, CaseIterable, Sendable {
    case top = "top"
    case topPlusBottom = "top-plus-bottom"
    case bottom = "bottom"
    case tClient = "t-client"
    case off = "off"
}

/// Composes the notification, verification and client badges around any content.
public struct TUIBadgedContent<Content: View>: View {
    public let badge: TUIBadgedContentBadge
    @ViewBuilder public let content: Content

    public init(badge: TUIBadgedContentBadge, @ViewBuilder content: () -> Content) {
        self.badge = badge
        self.content = content()
    }

    public var body: some View {
        content
            .overlay(alignment: .topTrailing) {
                if badge == .top || badge == .topPlusBottom {
                    TUINotificationBadge("1", size: .medium)
                        .offset(x: 8, y: -8)
                }
            }
            .overlay(alignment: .bottomTrailing) {
                switch badge {
                case .bottom, .topPlusBottom:
                    Image("tui-badged-content-check", bundle: .module)
                        .renderingMode(.template)
                        .resizable()
                        .scaledToFit()
                        .frame(width: 8.125, height: 5.625)
                        .foregroundStyle(TUIColor.named("Text/Primary On Dark"))
                        .frame(width: 16, height: 16)
                        .background(TUIColor.named("Background/Neutral 4"), in: Circle())
                        .padding(1)
                        .background(TUIColor.named("Background/Base"), in: Circle())
                        .offset(x: 8, y: 8)
                        .accessibilityLabel("Подтверждено")
                case .tClient:
                    TUIClientBadge()
                        .overlay(Circle().strokeBorder(TUIColor.named("Background/Base"), lineWidth: 2))
                        .offset(x: 4, y: 4)
                case .top, .off:
                    EmptyView()
                }
            }
    }
}

import SwiftUI

/// Transaction detail summary used in operation-result screens.
public struct TUIBlockDetails: View {
    public var titleValueText: String
    public var titleDescriptionText: String
    public var amountDescriptionText: String
    public var commentText: String
    public var showAmount: Bool
    public var showAmountDescription: Bool
    public var showAmountDescription2: Bool
    public var showBadges: Bool
    public var showComment: Bool
    public var showStatus: Bool
    public var showTitleDescription: Bool
    public var skeleton: Bool
    public var preview: Image?
    public var iconStatus: Image?

    public init(
        titleValueText: String = "TitleValue",
        titleDescriptionText: String = "TitleDescription",
        amountDescriptionText: String = "AmountDescription",
        commentText: String = "Comment",
        showAmount: Bool = true,
        showAmountDescription: Bool = true,
        showAmountDescription2: Bool = false,
        showBadges: Bool = true,
        showComment: Bool = true,
        showStatus: Bool = true,
        showTitleDescription: Bool = true,
        skeleton: Bool = false,
        preview: Image? = nil,
        iconStatus: Image? = nil
    ) {
        self.titleValueText = titleValueText
        self.titleDescriptionText = titleDescriptionText
        self.amountDescriptionText = amountDescriptionText
        self.commentText = commentText
        self.showAmount = showAmount
        self.showAmountDescription = showAmountDescription
        self.showAmountDescription2 = showAmountDescription2
        self.showBadges = showBadges
        self.showComment = showComment
        self.showStatus = showStatus
        self.showTitleDescription = showTitleDescription
        self.skeleton = skeleton
        self.preview = preview
        self.iconStatus = iconStatus
    }

    public var body: some View {
        VStack(spacing: 0) {
            avatar
                .frame(height: 80)

            VStack(spacing: TUISpacing.x1) {
                if skeleton {
                    TUISkeleton(width: 92, height: 14)
                } else {
                    Text(titleValueText)
                        .tuiTypography(.bodyLarge)
                        .foregroundStyle(TUIColor.named("Text/Primary"))
                        .multilineTextAlignment(.center)
                }

                if showTitleDescription {
                    if skeleton {
                        TUISkeleton(width: 70, height: 10)
                    } else {
                        Text(titleDescriptionText)
                            .tuiTypography(.uiSmall)
                            .foregroundStyle(TUIColor.named("Text/Secondary"))
                            .multilineTextAlignment(.center)
                    }
                }
            }
            .frame(maxWidth: .infinity)
            .padding(.top, TUISpacing.x4)

            if showAmount {
                VStack(spacing: TUISpacing.x1) {
                    if skeleton {
                        TUISkeleton(width: 127, height: 24)
                    } else {
                        Text("−123\u{2006}₽")
                            .tuiTypography(.numberXLarge)
                            .foregroundStyle(TUIColor.named("Text/Primary"))
                    }
                    if showAmountDescription {
                        if skeleton {
                            TUISkeleton(width: 70, height: 10)
                        } else {
                            Text(amountDescriptionText)
                                .tuiTypography(.uiSmall)
                                .foregroundStyle(TUIColor.named("Text/Secondary"))
                                .multilineTextAlignment(.center)
                        }
                    }
                }
                .padding(.top, TUISpacing.x5)
                .frame(maxWidth: .infinity)
            }

            if showAmountDescription2 {
                Group {
                    if skeleton {
                        TUISkeleton(width: 48, height: 12)
                    } else {
                        Text("ExtraDescription")
                            .tuiTypography(.uiSmall)
                            .foregroundStyle(TUIColor.named("Text/Secondary"))
                            .multilineTextAlignment(.center)
                    }
                }
                .frame(maxWidth: .infinity)
                .padding(.top, TUISpacing.x4)
            }

            if showComment {
                comment
                    .padding(.top, 9)
            }

            if showBadges {
                if skeleton {
                    Capsule()
                        .fill(TUIColor.named("Service/Skeleton"))
                        .frame(width: 82, height: 24)
                        .padding(.top, TUISpacing.x5)
                } else {
                    badge
                        .padding(.top, TUISpacing.x5)
                }
            }

            if showStatus {
                Group {
                    if skeleton {
                        TUISkeleton(width: 48, height: 12)
                    } else {
                        HStack(spacing: TUISpacing.x1) {
                            if let iconStatus {
                                iconStatus
                                    .resizable()
                                    .frame(width: 16, height: 16)
                            } else {
                                Image("tui-block-details-clock", bundle: .module)
                                    .renderingMode(.template)
                                    .resizable()
                                    .frame(width: 16, height: 16)
                                    .foregroundStyle(TUIColor.named("Background/Neutral 4"))
                            }
                            Text("Status")
                                .tuiTypography(.uiSmall)
                                .foregroundStyle(TUIColor.named("Text/Secondary"))
                        }
                    }
                }
                .padding(.top, TUISpacing.x5)
            }
        }
        .padding(.horizontal, TUISpacing.x4)
        .padding(.top, TUISpacing.x4)
        .padding(.bottom, TUISpacing.x8)
        .frame(maxWidth: .infinity)
        .accessibilityElement(children: .contain)
        .accessibilityLabel("Детали операции")
    }

    @ViewBuilder
    private var avatar: some View {
        if skeleton {
            Circle()
                .fill(TUIColor.named("Service/Skeleton"))
                .frame(width: 80, height: 80)
        } else if let preview {
            preview
                .resizable()
                .scaledToFill()
                .frame(width: 80, height: 80)
                .clipShape(Circle())
        } else {
            Image("tui-block-details-avatar", bundle: .module)
                .resizable()
                .interpolation(.high)
                .frame(width: 80, height: 80)
                .clipShape(Circle())
        }
    }

    private var comment: some View {
        VStack(spacing: 0) {
            Image(skeleton ? "tui-block-details-skeleton-tail" : "tui-block-details-comment-tail", bundle: .module)
                .resizable()
                .frame(width: 24, height: 12)
            if skeleton {
                TUISkeleton(width: 92, height: 34)
                    .clipShape(RoundedRectangle(cornerRadius: TUIRadius.xLarge))
            } else {
                Text(commentText)
                    .tuiTypography(.bodyMedium)
                    .foregroundStyle(TUIColor.named("Text/Primary On Dark"))
                    .padding(.horizontal, TUISpacing.x3)
                    .padding(.vertical, TUISpacing.x2)
                    .frame(minWidth: 64)
                    .background(TUIColor.named("Background/Accent 2"), in: RoundedRectangle(cornerRadius: TUIRadius.xLarge))
            }
        }
    }

    private var badge: some View {
        HStack(spacing: 0) {
            Image("tui-block-details-crown", bundle: .module)
                .resizable()
                .frame(width: 14, height: 11)
                .frame(width: 16, height: 16)
                .padding(.leading, TUISpacing.x1)
            Text("Badge")
                .tuiTypography(.uiSmallBold)
                .foregroundStyle(TUIColor.named("Text/Primary"))
                .padding(.horizontal, TUISpacing.x1)
                .padding(.vertical, 3.5)
        }
        .frame(minHeight: 24)
        .background(TUIColor.named("Background/Accent 1"), in: Capsule())
    }
}

import SwiftUI

public enum TUIBlockStatusType: String, CaseIterable, Sendable {
    case fullscreen = "Fullscreen"
    case card = "Card"
}

/// Zero-state and error-state content block with the iOS Fullscreen and Card layouts.
public struct TUIBlockStatus: View {
    @Environment(\.colorScheme) private var colorScheme
    public let type: TUIBlockStatusType
    public let title: String
    public let text: String
    public let showsButton: Bool
    public let showsSecondaryButton: Bool
    public let showsImage: Bool
    public let showsTitle: Bool
    public let showsText: Bool
    public let primaryAction: () -> Void
    public let secondaryAction: () -> Void

    public var figmaNodeID: String {
        switch (type, showsButton) {
        case (.fullscreen, true): "43816:296051"
        case (.card, true): "46555:321088"
        case (.fullscreen, false): "46719:307391"
        case (.card, false): "46719:307399"
        }
    }

    public init(
        type: TUIBlockStatusType = .fullscreen,
        title: String = "Title",
        text: String = "Text",
        showsButton: Bool = true,
        showsSecondaryButton: Bool = false,
        showsImage: Bool = true,
        showsTitle: Bool = true,
        showsText: Bool = true,
        primaryAction: @escaping () -> Void = {},
        secondaryAction: @escaping () -> Void = {}
    ) {
        self.type = type
        self.title = title
        self.text = text
        self.showsButton = showsButton
        self.showsSecondaryButton = showsSecondaryButton
        self.showsImage = showsImage
        self.showsTitle = showsTitle
        self.showsText = showsText
        self.primaryAction = primaryAction
        self.secondaryAction = secondaryAction
    }

    public var body: some View {
        VStack(spacing: 0) {
            if showsImage {
                image
                    .padding(.bottom, type == .fullscreen ? TUISpacing.x6 : TUISpacing.x4)
            }

            textContent

            if showsButton {
                buttons
                    .padding(.top, type == .fullscreen ? TUISpacing.x6 : 0)
            }
        }
        .frame(width: type == .card ? 335 : 375)
        .padding(.horizontal, type == .card ? TUISpacing.x5 : 0)
        .padding(.top, type == .card ? TUISpacing.x8 : 0)
        .padding(.bottom, type == .card ? TUISpacing.x5 : 0)
        .frame(minHeight: type == .card && showsImage && showsTitle && showsText ? (showsButton ? 214 : 182) : nil)
        .background {
            if type == .card {
                RoundedRectangle(cornerRadius: TUIRadius.xLarge)
                    .fill(TUIColor.named("Background/Neutral 1", fallback: 0xF7F7F8))
            }
        }
        .accessibilityElement(children: .contain)
        .accessibilityIdentifier(figmaNodeID)
    }

    @ViewBuilder
    private var image: some View {
        if type == .fullscreen {
            ZStack {
                Image(
                    colorScheme == .dark
                        ? "tui-block-status-magnifier-bubble-dark"
                        : "tui-block-status-magnifier-bubble",
                    bundle: .module
                )
                    .resizable()
                    .frame(width: 116.36, height: 116.36)
                Image(
                    colorScheme == .dark
                        ? "tui-block-status-magnifier-handle-dark"
                        : "tui-block-status-magnifier-handle",
                    bundle: .module
                )
                    .resizable()
                    .frame(width: 93.91, height: 92.08)
                    .offset(x: 4.5, y: 1.5)
            }
            .frame(width: 128, height: 128)
            .accessibilityHidden(true)
        } else {
            Image("tui-block-status-alert-vector", bundle: .module)
                .renderingMode(.template)
                .resizable()
                .foregroundStyle(.white)
                .frame(width: 24, height: 24)
                .frame(width: 56, height: 56)
                .background(TUIColor.named("Background/Neutral 4", fallback: 0xBFC2C6), in: Circle())
                .accessibilityHidden(true)
        }
    }

    private var textContent: some View {
        VStack(spacing: TUISpacing.x2) {
            if showsTitle {
                Text(title)
                    .tuiTypography(.headingSmall)
                    .foregroundStyle(TUIColor.textPrimary)
                    .frame(maxWidth: 290)
                    .fixedSize(horizontal: false, vertical: true)
            }
            if showsText {
                Text(text)
                    .tuiTypography(.bodyMedium)
                    .foregroundStyle(TUIColor.textSecondary)
                    .frame(maxWidth: 290)
                    .fixedSize(horizontal: false, vertical: true)
            }
        }
        .multilineTextAlignment(.center)
        .frame(maxWidth: type == .card ? .infinity : nil)
        .accessibilityElement(children: .combine)
    }

    private var buttons: some View {
        VStack(spacing: TUISpacing.x2) {
            if showsSecondaryButton && type == .card {
                actionButton(title: "Label", action: secondaryAction, hasBackground: true)
                    .padding(.top, TUISpacing.x6)
            }
            actionButton(
                title: "Label",
                action: primaryAction,
                hasBackground: type == .fullscreen || (type == .card && !showsSecondaryButton)
            )
            if showsSecondaryButton && type == .fullscreen {
                actionButton(title: "Label", action: secondaryAction, hasBackground: false)
            }
        }
        .frame(width: type == .fullscreen ? 290 : nil)
        .frame(maxWidth: type == .card ? .infinity : nil)
    }

    private func actionButton(title: String, action: @escaping () -> Void, hasBackground: Bool) -> some View {
        Button(action: action) {
            Text(title)
                .tuiTypography(.bodyMedium)
                .foregroundStyle(TUIColor.action)
                .padding(.horizontal, TUISpacing.x2)
                .padding(.vertical, TUISpacing.x0_5 + 1)
                .frame(minHeight: 44)
                .background {
                    if hasBackground {
                        RoundedRectangle(cornerRadius: TUIRadius.medium)
                            .fill(TUIColor.named("Background/Neutral 1", fallback: 0xF7F7F8))
                    }
                }
                .contentShape(RoundedRectangle(cornerRadius: TUIRadius.medium))
        }
        .buttonStyle(.plain)
    }
}

