import SwiftUI

/// The small measurement square used to preview the TUI spacing scale.
public struct TUISpacingIndicator: View {
    public enum Size: String, CaseIterable, Identifiable, Sendable {
        case zero = "0"
        case x2 = "01 - 2px"
        case x4 = "02 - 4px"
        case x8 = "03 - 8px"
        case x12 = "04 - 12px"
        case x16 = "05 - 16px"
        case x20 = "06 - 20px"
        case x24 = "07 - 24px"
        case x32 = "08 - 32px"
        case x40 = "09 - 40px"
        case x48 = "10 - 48px"

        public var id: String { rawValue }

        public var points: CGFloat {
            switch self {
            case .zero: TUISpacing.x0
            case .x2: TUISpacing.x0_5
            case .x4: TUISpacing.x1
            case .x8: TUISpacing.x2
            case .x12: TUISpacing.x3
            case .x16: TUISpacing.x4
            case .x20: TUISpacing.x5
            case .x24: TUISpacing.x6
            case .x32: TUISpacing.x8
            case .x40: TUISpacing.x10
            case .x48: TUISpacing.x12
            }
        }

        public var label: String {
            switch self {
            case .zero: "0"
            case .x2: "2"
            case .x4: "4"
            case .x8: "8"
            case .x12: "12"
            case .x16: "16"
            case .x20: "20"
            case .x24: "24"
            case .x32: "32"
            case .x40: "40"
            case .x48: "48"
            }
        }

        public var figmaVariantIDs: (visible: String, hidden: String?) {
            switch self {
            case .zero: ("28406:482307", nil)
            case .x2: ("28406:482303", "28406:482305")
            case .x4: ("28406:482299", "28406:482301")
            case .x8: ("28406:482295", "28406:482297")
            case .x12: ("28406:482291", "28406:482293")
            case .x16: ("28406:482287", "28406:482289")
            case .x20: ("28406:482283", "28406:482285")
            case .x24: ("28406:482279", "28406:482281")
            case .x32: ("28406:482275", "28406:482277")
            case .x40: ("28406:482271", "28406:482273")
            case .x48: ("28406:482267", "28406:482269")
            }
        }

        fileprivate var labelSize: CGFloat {
            switch self {
            case .zero: 0
            case .x2: 2
            case .x4: 4
            case .x8: 5
            case .x12: 6
            default: 8
            }
        }
    }

    public let size: Size
    public let visible: Bool

    public init(size: Size = .x48, visible: Bool = true) {
        self.size = size
        self.visible = visible
    }

    public var figmaVariantID: String {
        if visible { return size.figmaVariantIDs.visible }
        return size.figmaVariantIDs.hidden ?? size.figmaVariantIDs.visible
    }

    public var body: some View {
        Group {
            if size == .zero {
                Color.clear
                    .frame(width: 1, height: 0)
            } else {
                ZStack {
                    TUIColor.named("Status/Negative Pale")
                    Text(size.label)
                        .font(.system(size: size.labelSize, weight: .regular, design: .default))
                        .foregroundStyle(TUIColor.named("Text/Negative"))
                        .lineLimit(1)
                        .minimumScaleFactor(1)
                }
                .frame(width: size.points, height: size.points)
                .clipped()
                .opacity(visible ? 1 : 0)
            }
        }
        .accessibilityLabel("Spacing \(size.label) points, \(visible ? "visible" : "hidden")")
        .accessibilityIdentifier(figmaVariantID)
    }
}

import SwiftUI

/// A reusable trailing swipe-action container that keeps the gesture and reveal behavior native to iOS.
public enum TUISwipeContents: String, CaseIterable, Sendable {
    case cell = "Cell"
    case card = "Card"

    public var figmaNodeID: String {
        switch self {
        case .cell: "53204:296102"
        case .card: "23373:45753"
        }
    }
}

public struct TUISwipeActions: ViewModifier {
    public let actions: [TUISwipeAction]

    public init(actions: [TUISwipeAction]) {
        self.actions = Array(actions.prefix(3))
    }

    public func body(content: Content) -> some View {
        content.swipeActions(edge: .trailing, allowsFullSwipe: false) {
            ForEach(actions) { action in
                Button(role: action.role, action: action.perform) { action.label }
                .tint(action.tint)
                .accessibilityLabel(action.title)
            }
        }
    }
}

public extension View {
    /// Adds native trailing swipe actions to this list row.
    func tuiSwipeActions(_ actions: [TUISwipeAction]) -> some View {
        modifier(TUISwipeActions(actions: actions))
    }
}

/// An action exposed by ``TUISwipeActions``. A custom label can render the exact icon or asset used by the consuming row.
public struct TUISwipeAction: Identifiable {
    public let id: UUID
    public let title: String
    public let role: ButtonRole?
    public let tint: Color
    fileprivate let label: AnyView
    private let action: () -> Void

    public init<Label: View>(
        _ title: String,
        role: ButtonRole? = nil,
        tint: Color = TUIColor.named("Background/Accent 2", fallback: 0x428BF9),
        @ViewBuilder label: () -> Label,
        action: @escaping () -> Void
    ) {
        self.id = UUID()
        self.title = title
        self.role = role
        self.tint = tint
        self.label = AnyView(label())
        self.action = action
    }

    public init(
        _ title: String,
        systemImage: String,
        role: ButtonRole? = nil,
        tint: Color = TUIColor.named("Background/Accent 2", fallback: 0x428BF9),
        action: @escaping () -> Void
    ) {
        self.init(title, role: role, tint: tint, label: { Image(systemName: systemImage) }, action: action)
    }

    fileprivate func perform() { action() }
}

import SwiftUI

/// A text block that can be expanded and collapsed, matching the iOS `tui-text-expandable` variants.
public struct TUITextExpandable: View {
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    public enum Size: String, CaseIterable, Sendable, Hashable {
        case uiSmall = "UI S"
        case bodyMedium = "Body M"
        case bodyLarge = "Body L"

        var typography: TUITypographyRole {
            switch self {
            case .uiSmall: .uiSmall
            case .bodyMedium: .bodyMedium
            case .bodyLarge: .bodyLarge
            }
        }

        var tracking: CGFloat {
            switch self {
            case .uiSmall: -0.08
            case .bodyMedium: -0.24
            case .bodyLarge: -0.41
            }
        }

        var collapsedHeight: CGFloat {
            switch self {
            case .uiSmall: 64
            case .bodyMedium: 90
            case .bodyLarge: 100
            }
        }

        var skeletonHeight: CGFloat {
            switch self {
            case .uiSmall: 64
            case .bodyMedium: 74
            case .bodyLarge: 82
            }
        }

        var skeletonAssetHeight: CGFloat {
            switch self {
            case .uiSmall: 56
            case .bodyMedium: 64
            case .bodyLarge: 72
            }
        }

        var rowHeight: CGFloat {
            switch self {
            case .uiSmall: 80
            case .bodyMedium: 106
            case .bodyLarge: 116
            }
        }
    }

    public enum Style: String, CaseIterable, Sendable, Hashable {
        case primary = "Primary"
        case secondary = "Secondary"
    }

    public let text: String
    public let size: Size
    public let style: Style
    public let showsMoreButton: Bool
    public let isSkeleton: Bool
    @State private var isExpanded = false

    public init(
        _ text: String,
        size: Size = .bodyMedium,
        style: Style = .primary,
        showsMoreButton: Bool = true,
        isSkeleton: Bool = false
    ) {
        self.text = text
        self.size = size
        self.style = style
        self.showsMoreButton = showsMoreButton
        self.isSkeleton = isSkeleton
    }

    public var body: some View {
        Group {
            if isSkeleton {
                skeletonContent
            } else {
                textContent
            }
        }
        .frame(maxWidth: .infinity, alignment: .leading)
        .padding(.horizontal, TUISpacing.x4)
        .padding(.vertical, TUISpacing.x2)
        .frame(width: size == .uiSmall && style == .secondary ? 360 : 375)
        .frame(height: isSkeleton ? size.skeletonHeight + 16 : (!isExpanded ? size.rowHeight : nil), alignment: .topLeading)
        .background(TUIColor.named("Background/Base", fallback: 0xFFFFFF))
        .accessibilityElement(children: .contain)
        .accessibilityIdentifier(figmaNodeID ?? "44305:306527")
        .onChange(of: size) { _, _ in isExpanded = false }
        .onChange(of: style) { _, _ in isExpanded = false }
        .onChange(of: showsMoreButton) { _, _ in isExpanded = false }
        .onChange(of: isSkeleton) { _, _ in isExpanded = false }
    }

    public var figmaNodeID: String? {
        switch (size, style, isSkeleton) {
        case (.bodyMedium, .primary, false): "44305:306528"
        case (.bodyMedium, .secondary, false): "44305:306611"
        case (.bodyLarge, .primary, false): "49780:289467"
        case (.bodyLarge, .secondary, false): "49780:289476"
        case (.uiSmall, .primary, false): "49808:291011"
        case (.uiSmall, .secondary, false): "49808:291020"
        case (.bodyLarge, .primary, true): "56039:297548"
        case (.bodyMedium, .primary, true): "56039:297557"
        case (.uiSmall, .primary, true): "56039:297566"
        case (_, .secondary, true): nil
        }
    }

    private var textColor: Color {
        TUIColor.named(style == .primary ? "Text/Primary" : "Text/Secondary", fallback: style == .primary ? 0x333333 : 0x9299A2)
    }

    private var textContent: some View {
        VStack(alignment: .trailing, spacing: TUISpacing.x2) {
            Text(text)
                .font(Font(TUIFigmaTextFont.regular(size: size.typography.metrics.size)))
                .tracking(size.tracking)
                .foregroundStyle(textColor)
                .fixedSize(horizontal: false, vertical: true)
                .frame(maxWidth: .infinity, alignment: .leading)
                .frame(height: isExpanded ? nil : size.collapsedHeight, alignment: .topLeading)
                .overlay(alignment: .bottomTrailing) {
                    if showsMoreButton && !isExpanded {
                        moreButton
                    }
                }
                .clipped()
            if showsMoreButton && isExpanded {
                Button("свернуть") {
                    withAnimation(reduceMotion ? nil : .default) { isExpanded = false }
                }
                .font(Font(TUIFigmaTextFont.regular(size: size.typography.metrics.size)))
                .tracking(size.tracking)
                .foregroundStyle(TUIColor.named("Text/Action", fallback: 0x428BF9))
                .buttonStyle(.plain)
                .accessibilityLabel("Свернуть текст")
            }
        }
    }

    private var moreButton: some View {
        Button {
            withAnimation(reduceMotion ? nil : .default) { isExpanded = true }
        } label: {
            Text("еще")
                .font(Font(TUIFigmaTextFont.regular(size: size.typography.metrics.size)))
                .tracking(size.tracking)
                .foregroundStyle(TUIColor.named("Text/Action", fallback: 0x428BF9))
                .fixedSize()
                .padding(.leading, TUISpacing.x2)
                .background(TUIColor.backgroundPrimary)
                .background(alignment: .leading) {
                    LinearGradient(
                        colors: [TUIColor.backgroundPrimary.opacity(0), TUIColor.backgroundPrimary],
                        startPoint: .leading,
                        endPoint: .trailing
                    )
                    .frame(width: TUISpacing.x6, height: size.typography.metrics.lineHeight)
                    .offset(x: -TUISpacing.x6)
                }
        }
        .buttonStyle(.plain)
        .accessibilityLabel("Показать весь текст")
    }

    private var skeletonContent: some View {
        Image(skeletonAssetName, bundle: .module)
            .resizable()
            .frame(width: 303, height: size.skeletonAssetHeight)
            .frame(maxWidth: .infinity, alignment: .leading)
            .padding(.top, 5)
            .frame(height: size.skeletonHeight, alignment: .topLeading)
            .accessibilityHidden(true)
    }

    private var skeletonAssetName: String {
        switch size {
        case .bodyLarge: "tui-text-expandable-skeleton-body-l"
        case .bodyMedium: "tui-text-expandable-skeleton-body-m"
        case .uiSmall: "tui-text-expandable-skeleton-ui-s"
        }
    }
}

